import {validateDocument,check,exact,identifier} from './document.mjs';
import {validateMp3,validateToraMesh} from './media-validate.mjs';
export const BUNDLE_LIMIT=64*1024*1024;
export async function hash(value){const bytes=typeof value==='string'?new globalThis.TextEncoder().encode(value):value;return 'sha256:'+Array.from(new Uint8Array(await globalThis.crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');}
async function browserDecodeImage(bytes,mime){check(typeof globalThis.createImageBitmap==='function','Image decoder required');const image=await globalThis.createImageBitmap(new globalThis.Blob([bytes],{type:mime}));try{check(image.width>0&&image.height>0&&image.width<=4096&&image.height<=4096,'Image dimensions exceed 4096 pixels');}finally{image.close();}}
export function projectBundle(project,assets){validateDocument(project);const data={};for(const asset of project.assets){check(typeof assets[asset.hash]==='string','Missing project asset');data[asset.hash]=assets[asset.hash];}const text=JSON.stringify({format:'tora-project-bundle',version:1,project,assets:data});check(new globalThis.TextEncoder().encode(text).length<=BUNDLE_LIMIT,'Project file exceeds 64 MiB');return text;}
export async function readProjectBundle(text,options={}){check(typeof text==='string'&&new globalThis.TextEncoder().encode(text).length<=BUNDLE_LIMIT,'Project file exceeds 64 MiB');let bundle;try{bundle=JSON.parse(text);}catch{throw Error('Invalid project JSON');}check(exact(bundle,['format','version','project','assets'])&&bundle.format==='tora-project-bundle'&&bundle.version===1,'Unsupported project bundle');const project=validateDocument(globalThis.structuredClone(bundle.project));check(/^[a-z][a-z0-9-]{1,47}$/.test(project.projectId)&&project.projectId!=='compose','Invalid project ID');check(bundle.assets&&typeof bundle.assets==='object'&&!Array.isArray(bundle.assets),'Missing project assets');const expected=new Set(project.assets.map(a=>a.hash));check(Object.keys(bundle.assets).length===expected.size&&Object.keys(bundle.assets).every(key=>expected.has(key)),'Unexpected project assets');for(const asset of project.assets){const result=await validateAssetData({id:asset.id,mime:asset.mime,rights:asset.rights,data:bundle.assets[asset.hash]},options);check(result.hash===asset.hash&&result.bytes===asset.bytes,'Asset hash or byte count mismatch');}project.revisionId='initial';return {project,assets:globalThis.structuredClone(bundle.assets)};}
export async function validateAssetData(input,{decodeImage=browserDecodeImage}={}){check(exact(input,['id','mime','data','rights'])&&identifier(input.id)&&typeof input.rights==='string'&&input.rights.trim()&&input.rights.length<=2048,'Describe the asset rights');check(typeof input.data==='string'&&input.data.length<=933336&&/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(input.data),'Invalid asset encoding');const bytes=Uint8Array.from(globalThis.atob(input.data),c=>c.charCodeAt(0));check(bytes.length>0&&bytes.length<=700000,'Asset exceeds 700,000 bytes');check(['image/png','image/jpeg','audio/wav','audio/mpeg','model/tora-mesh'].includes(input.mime),'Use PNG, JPEG, PCM WAV, MP3 or Tora 3D mesh');
 if(input.mime==='audio/wav'){validateWav(bytes);}else if(input.mime==='audio/mpeg'){validateMp3(bytes,'Invalid MP3 audio');}else if(input.mime==='model/tora-mesh'){validateToraMesh(bytes,'Invalid Tora 3D mesh');}else{check(input.mime==='image/png'?bytes.slice(0,8).join(',')==='137,80,78,71,13,10,26,10':bytes[0]===255&&bytes[1]===216&&bytes[2]===255,'Asset type does not match its contents');await decodeImage(bytes,input.mime);}
 return {...input,hash:await hash(bytes),bytes:bytes.length,provenance:'Uploaded in the browser editor; content hash and browser media validation.'};
}
function validateWav(bytes){const v=new DataView(bytes.buffer),text=(start,end)=>String.fromCharCode(...bytes.slice(start,end));check(bytes.length>=44&&text(0,4)==='RIFF'&&text(8,12)==='WAVE'&&v.getUint32(4,true)+8===bytes.length,'Invalid WAV');let offset=12,align=0,rate=0,size=0;while(offset+8<=bytes.length){const kind=text(offset,offset+4),n=v.getUint32(offset+4,true);check(offset+8+n<=bytes.length,'Invalid WAV chunk');if(kind==='fmt '){check(n>=16&&v.getUint16(offset+8,true)===1,'Use PCM WAV');const channels=v.getUint16(offset+10,true),bits=v.getUint16(offset+22,true);rate=v.getUint32(offset+12,true);align=channels*bits/8;check([1,2].includes(channels)&&[8,16].includes(bits)&&rate>=8000&&rate<=48000&&v.getUint16(offset+20,true)===align&&v.getUint32(offset+16,true)===rate*align,'Unsupported PCM WAV');}if(kind==='data'){check(n>0&&!size,'Invalid WAV data');size=n;}offset+=8+n+n%2;}check(align&&size&&size%align===0&&size/align/rate<=120&&offset===bytes.length,'Invalid WAV duration');}
